/*selectMasterMdCmBuyerMsDsHeadDetailPop_v2*/ SELECT A.MSDS_NO, A.DESCRIPTION, A.SPECIFICATION, A.UNIT_MEASURE, A.MAKER_NAME, A.ORIGIN_CODE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE) AS ORIGIN_NM, (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.ADD_USER_ID) AS ADD_USER_NM, A.CMC_HARMFUL_YN, A.LAST_REVISION_DATE, A.CMC_USE_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'CM02' AND CODE = A.CMC_USE_CODE AND FLAG = 'Y') AS CMC_USE_NAME, A.CMC_USE_NOTE, A.CMC_INFO_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'CM06' AND CODE = A.CMC_INFO_CODE AND FLAG = 'Y') AS CMC_INFO_NAME, TO_CHAR(A.CMC_INFO_LEVEL) AS CMC_INFO_LEVEL, A.MSDS_SUBMISSION_NUMBER FROM KEPMSDSHD A WHERE 1=1
AND A.MSDS_NO = #{st_msds_no}
ORDER BY A.MSDS_NO

/*selectMasterMdCmBuyerMsDsHeadCasDetailPop_v2*/ SELECT TO_CHAR(LEVEL) AS NO, REGEXP_SUBSTR(T.CAS_NO,'[^/]*',1,LEVEL) AS CAS_NO, REGEXP_SUBSTR(T.MIN_MAKE_RATE,'[^/]*',1,LEVEL) AS CAS_NO_MIN, REGEXP_SUBSTR(T.MAX_MAKE_RATE,'[^/]*',1,LEVEL) AS CAS_NO_MAX, REGEXP_SUBSTR(T.CML_HARMFUL_YN,'[^/]*',1,LEVEL) AS CAS_NO_HARMFUL, REGEXP_SUBSTR(T.CML_PRE_TROUBLE_YN,'[^/]*',1,LEVEL) AS CAS_NO_PREPARE, REGEXP_SUBSTR(T.CML_LIMIT_OBJECT_YN,'[^/]*',1,LEVEL) AS CAS_NO_LIMIT, REGEXP_SUBSTR(T.CML_ACUT_HAZD_YN,'[^/]*',1,LEVEL) AS CAS_NO_ACUT, REGEXP_SUBSTR(T.CML_CHRO_HAZD_YN,'[^/]*',1,LEVEL) AS CAS_NO_CHRO, REGEXP_SUBSTR(T.CML_ECOL_HAZD_YN,'[^/]*',1,LEVEL) AS CAS_NO_ECOL FROM ( SELECT A.* FROM KEPMSDSHD A WHERE 1=1
AND A.MSDS_NO = #{st_msds_no}
ORDER BY A.MSDS_NO
) T CONNECT BY LEVEL <= REGEXP_COUNT(T.CAS_NO, '/') +1 AND PRIOR ROWID = ROWID AND PRIOR SYS_GUID() IS NOT NULL AND REGEXP_SUBSTR(T.CAS_NO,'[^/]*',1,LEVEL) IS NOT NULL

mapper.update:

/* deleteMasterMdCmMsdsDetail */
UPDATE	KEPMSDSDT
SET		STATUS = #{status},
		CHANGE_USER_ID = #{user_id},
		CHANGE_DATE = SYSDATE
WHERE	MSDS_NO = #{msds_no}
AND		FILE_NO = #{file_no}
AND		REVISION = #{revision}


/*saveMasterMsdsMapping*/
UPDATE KEPRQDT 
   SET MSDS_NO = #{MSDS_NO}
       ,MSDS_A_CONFIRM_ID = #{st_user_id}



       ,MSDS_STATUS =#{p_return}



WHERE BUYER =#{p_buyer}
   AND QUOTATION_NO = #{p_quotation_no}
   AND QUOTATION_SEQ =#{p_quotation_seq}
   AND REVISION = #{p_revision}
   AND MSDS_YN = 'Y'


/*saveMasterMsdsByitMapping*/
UPDATE	ICOMBYIT
SET		MSDS_NO = DECODE(#{MSDS_NO}, 'MS88888888', '', #{MSDS_NO}),
		MSDS_YN ='Y',
		MATERIAL_TYPE = (SELECT DECODE(CMC_HARMFUL_YN, 'Y', 'H', NULL) FROM KEPMSDSHD WHERE MSDS_NO = #{MSDS_NO})
WHERE	BUYER = #{p_buyer}
AND		BUYER_ITEM_NO = #{p_buyer_item_no}


/*updateMasterMdCmMsdsDetail*/
INSERT INTO  KEPMSDSDT(
	MSDS_NO
  ,FILE_NO
  ,REVISION
  ,STATUS
  ,IMAGE_KEY
  ,FILE_DATE
  ,NOTE
  ,ADD_USER_ID
  ,ADD_DATE
  ,CHANGE_USER_ID
  ,CHANGE_DATE)
  VALUES(
  	 #{msds_no}
  	, #{file_no}
  	, (SELECT NVL(MAX(A.REVISION),0)+1 FROM KEPMSDSDT A 
  			WHERE A.MSDS_NO = #{msds_no}
  			AND A.FILE_NO = #{file_no})
  	,'C'
  	, #{image_key}
  	, TO_CHAR(SYSDATE, 'YYYYMMDD')
  	, #{note}
  	, #{user_id}
  	, SYSDATE
  	, #{user_id}
  	, SYSDATE				  			
  )


/* updateMasterMdCmMsdsHarmfulByit */
UPDATE	ICOMBYIT
SET		MATERIAL_TYPE = DECODE(#{cmc_harmful_yn}, 'Y', 'H', NULL)
WHERE	MSDS_NO = #{msds_no}
AND		MSDS_NO IS NOT NULL

mapper.select:

/* selectMasterMdCmMsdsDetailChange */
SELECT	DECODE(COUNT(*), 0, 'Y', 'N') AS CHANGE_YN
FROM	KEPMSDSDT
WHERE	1=1
AND		MSDS_NO = #{msds_no}
AND		FILE_NO = #{file_no}
AND		REVISION = #{revision}
AND		IMAGE_KEY = #{image_key}
AND		NVL(NOTE, 'X') = NVL(#{note}, 'X')

mapper.update:

/* updateMasterMdCmCatalogMsdsClean */
UPDATE	ICOMBYIT A
SET		A.MSDS_NO = F_HST_ICOMBYIT(A.BUYER, A.BUYER_ITEM_NO, 'MSDS_NO', '', #{st_user_id}),
		A.MSDS_YN = (SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE COD.CODE = A.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.FLAG = 'Y'),
		A.MATERIAL_TYPE = NULL
WHERE	1=1
AND		A.BUYER = #{BUYER}
AND		A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
